import numpy as np

SIZE = 20


def empty_grid(size=SIZE):
    return np.zeros((size, size), dtype=np.uint8)


def place_pattern(grid, pattern, top, left):
    for dr, row in enumerate(pattern):
        for dc, ch in enumerate(row):
            if ch == '#':
                grid[(top + dr) % grid.shape[0], (left + dc) % grid.shape[1]] = 1
    return grid


def step(grid):
    # Count live neighbours with wraparound (toroidal) edges
    neighbours = sum(
        np.roll(np.roll(grid, dr, axis=0), dc, axis=1)
        for dr in (-1, 0, 1) for dc in (-1, 0, 1) if (dr, dc) != (0, 0)
    )
    born = (grid == 0) & (neighbours == 3)
    survive = (grid == 1) & ((neighbours == 2) | (neighbours == 3))
    return (born | survive).astype(np.uint8)


def render(grid):
    return "\n".join("".join('#' if cell else '.' for cell in row) for row in grid)


GLIDER = [
    ".#.",
    "..#",
    "###",
]
BLINKER = [
    "###",
]


def run(total_generations=30, print_every=10):
    grid = empty_grid()
    place_pattern(grid, GLIDER, 1, 1)
    place_pattern(grid, BLINKER, 15, 14)
    print("Generation 0:")
    print(render(grid))
    print()
    for gen in range(1, total_generations + 1):
        grid = step(grid)
        if gen % print_every == 0:
            print(f"Generation {gen}:")
            print(render(grid))
            print()
    return grid


if __name__ == '__main__':
    final = run()
    print("Live cells at generation 30:", int(final.sum()))
